def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    if not cells:
        return {}

    MISSING = object()
    UNVISITED = object()
    IN_PROGRESS = object()

    OP_PUSH_INT = 0
    OP_PUSH_NONE = 1
    OP_LOAD_CELL = 2
    OP_NEG = 3
    OP_BINOP = 4
    OP_JMP = 5
    OP_JMP_IF_ERR = 6
    OP_JMP_IF_ERR_POP1 = 7
    OP_CMP_JMP_FALSE = 8
    OP_RANGE_AGG = 9
    OP_AGG_VAL = 10
    OP_FINISH_AGG = 11

    AGG_SUM = 0
    AGG_MIN = 1
    AGG_MAX = 2

    memo = [MISSING] * 2574
    raw_formulas: list[str | None] = [None] * 2574
    cell_entries: list[tuple[str, int]] = []

    for name, content in cells.items():
        idx = (int(name[1:]) - 1) * 26 + (ord(name[0]) - 65)
        cell_entries.append((name, idx))
        s = content.strip()
        if s.startswith("="):
            memo[idx] = UNVISITED
            raw_formulas[idx] = s[1:]
        else:
            memo[idx] = int(s)

    def tokenize(expr: str) -> list[tuple[str, object]]:
        tokens: list[tuple[str, object]] = []
        i = 0
        n = len(expr)
        while i < n:
            ch = expr[i]
            if ch.isspace():
                i += 1
            elif "0" <= ch <= "9":
                j = i + 1
                while j < n and "0" <= expr[j] <= "9":
                    j += 1
                tokens.append(("INT", int(expr[i:j])))
                i = j
            elif "A" <= ch <= "Z":
                j = i + 1
                while j < n and (
                    ("A" <= expr[j] <= "Z") or ("0" <= expr[j] <= "9")
                ):
                    j += 1
                word = expr[i:j]
                if word in ("SUM", "MIN", "MAX", "IF"):
                    tokens.append(("FUNC", word))
                else:
                    idx = (int(word[1:]) - 1) * 26 + (ord(word[0]) - 65)
                    tokens.append(("CELL", idx))
                i = j
            elif ch == "<":
                if i + 1 < n and expr[i + 1] in ("=", ">"):
                    tokens.append(("CMP", expr[i : i + 2]))
                    i += 2
                else:
                    tokens.append(("CMP", "<"))
                    i += 1
            elif ch == ">":
                if i + 1 < n and expr[i + 1] == "=":
                    tokens.append(("CMP", ">="))
                    i += 2
                else:
                    tokens.append(("CMP", ">"))
                    i += 1
            elif ch == "=":
                tokens.append(("CMP", "="))
                i += 1
            else:
                tokens.append((ch, None))
                i += 1
        tokens.append(("EOF", None))
        return tokens

    def compile_formula(expr: str) -> list[tuple]:
        tokens = tokenize(expr)
        code: list[tuple] = []
        pos = 0

        def parse_expr(min_prec: int = 0) -> None:
            nonlocal pos
            neg = False
            while tokens[pos][0] == "-":
                neg = not neg
                pos += 1

            tok_type, tok_val = tokens[pos]
            if tok_type == "INT":
                pos += 1
                code.append((OP_PUSH_INT, tok_val))
            elif tok_type == "CELL":
                pos += 1
                code.append((OP_LOAD_CELL, tok_val))
            elif tok_type == "(":
                pos += 1
                parse_expr(0)
                pos += 1
            elif tok_type == "FUNC":
                pos += 2
                if tok_val == "IF":
                    parse_expr(0)
                    j1 = len(code)
                    code.append((OP_JMP_IF_ERR, 0))
                    cmp_op = tokens[pos][1]
                    pos += 1
                    parse_expr(0)
                    j2 = len(code)
                    code.append((OP_JMP_IF_ERR_POP1, 0))
                    j_else = len(code)
                    code.append((OP_CMP_JMP_FALSE, cmp_op, 0))
                    pos += 1
                    parse_expr(0)
                    j_end = len(code)
                    code.append((OP_JMP, 0))
                    pos += 1
                    else_label = len(code)
                    parse_expr(0)
                    pos += 1
                    end_label = len(code)
                    code[j1] = (OP_JMP_IF_ERR, end_label)
                    code[j2] = (OP_JMP_IF_ERR_POP1, end_label)
                    code[j_else] = (OP_CMP_JMP_FALSE, cmp_op, else_label)
                    code[j_end] = (OP_JMP, end_label)
                else:
                    if tok_val == "SUM":
                        agg_kind = AGG_SUM
                        code.append((OP_PUSH_INT, 0))
                    elif tok_val == "MIN":
                        agg_kind = AGG_MIN
                        code.append((OP_PUSH_NONE,))
                    else:
                        agg_kind = AGG_MAX
                        code.append((OP_PUSH_NONE,))

                    err_jumps: list[int] = []
                    while True:
                        if (
                            tokens[pos][0] == "CELL"
                            and tokens[pos + 1][0] == ":"
                        ):
                            r1, c1 = divmod(tokens[pos][1], 26)
                            r2, c2 = divmod(tokens[pos + 2][1], 26)
                            pos += 3
                            min_r, max_r = (r1, r2) if r1 <= r2 else (r2, r1)
                            min_c, max_c = (c1, c2) if c1 <= c2 else (c2, c1)
                            err_jumps.append(len(code))
                            code.append(
                                (
                                    OP_RANGE_AGG,
                                    agg_kind,
                                    min_r,
                                    max_r,
                                    min_c,
                                    max_c,
                                    0,
                                )
                            )
                        else:
                            parse_expr(0)
                            err_jumps.append(len(code))
                            code.append((OP_AGG_VAL, agg_kind, 0))
                        if tokens[pos][0] == ",":
                            pos += 1
                        else:
                            break
                    pos += 1
                    if agg_kind != AGG_SUM:
                        code.append((OP_FINISH_AGG,))
                    end_label = len(code)
                    for j in err_jumps:
                        code[j] = code[j][:-1] + (end_label,)

            if neg:
                code.append((OP_NEG,))

            while True:
                op_tok = tokens[pos][0]
                if op_tok == "+" or op_tok == "-":
                    prec = 1
                elif op_tok == "*" or op_tok == "/":
                    prec = 2
                else:
                    break
                if prec < min_prec:
                    break
                pos += 1
                j_err = len(code)
                code.append((OP_JMP_IF_ERR, 0))
                parse_expr(prec + 1)
                code.append((OP_BINOP, op_tok))
                code[j_err] = (OP_JMP_IF_ERR, len(code))

        parse_expr(0)
        return code

    for _, start_idx in cell_entries:
        if memo[start_idx] is not UNVISITED:
            continue

        memo[start_idx] = IN_PROGRESS
        frames = []
        cell_idx = start_idx
        code = compile_formula(raw_formulas[start_idx])
        pc = 0
        stack = []
        cursor = None

        while True:
            if pc == len(code):
                memo[cell_idx] = stack[0]
                if not frames:
                    break
                cell_idx, code, pc, stack, cursor = frames.pop()
                continue

            instr = code[pc]
            op = instr[0]

            if op == OP_PUSH_INT:
                stack.append(instr[1])
                pc += 1
            elif op == OP_PUSH_NONE:
                stack.append(None)
                pc += 1
            elif op == OP_LOAD_CELL:
                target = instr[1]
                v = memo[target]
                if v is MISSING:
                    stack.append(0)
                    pc += 1
                elif v is UNVISITED:
                    frames.append((cell_idx, code, pc, stack, cursor))
                    memo[target] = IN_PROGRESS
                    cell_idx = target
                    code = compile_formula(raw_formulas[target])
                    pc = 0
                    stack = []
                    cursor = None
                elif v is IN_PROGRESS:
                    stack.append("#CYCLE!")
                    pc += 1
                else:
                    stack.append(v)
                    pc += 1
            elif op == OP_NEG:
                v = stack[-1]
                if type(v) is not str:
                    stack[-1] = -v
                pc += 1
            elif op == OP_BINOP:
                r = stack.pop()
                l = stack[-1]
                if type(r) is str:
                    stack[-1] = r
                else:
                    bop = instr[1]
                    if bop == "+":
                        stack[-1] = l + r
                    elif bop == "-":
                        stack[-1] = l - r
                    elif bop == "*":
                        stack[-1] = l * r
                    else:
                        if r == 0:
                            stack[-1] = "#DIV/0!"
                        else:
                            q = abs(l) // abs(r)
                            stack[-1] = -q if (l < 0) != (r < 0) else q
                pc += 1
            elif op == OP_JMP:
                pc = instr[1]
            elif op == OP_JMP_IF_ERR:
                if type(stack[-1]) is str:
                    pc = instr[1]
                else:
                    pc += 1
            elif op == OP_JMP_IF_ERR_POP1:
                if type(stack[-1]) is str:
                    err = stack.pop()
                    stack[-1] = err
                    pc = instr[1]
                else:
                    pc += 1
            elif op == OP_CMP_JMP_FALSE:
                r = stack.pop()
                l = stack.pop()
                cmp_op = instr[1]
                if cmp_op == "=":
                    cond = l == r
                elif cmp_op == "<>":
                    cond = l != r
                elif cmp_op == "<":
                    cond = l < r
                elif cmp_op == "<=":
                    cond = l <= r
                elif cmp_op == ">":
                    cond = l > r
                else:
                    cond = l >= r
                if cond:
                    pc += 1
                else:
                    pc = instr[2]
            elif op == OP_AGG_VAL:
                val = stack.pop()
                if type(val) is str:
                    stack[-1] = val
                    pc = instr[2]
                else:
                    agg_kind = instr[1]
                    acc = stack[-1]
                    if agg_kind == AGG_SUM:
                        stack[-1] = acc + val
                    elif agg_kind == AGG_MIN:
                        if acc is None or val < acc:
                            stack[-1] = val
                    else:
                        if acc is None or val > acc:
                            stack[-1] = val
                    pc += 1
            elif op == OP_FINISH_AGG:
                if stack[-1] is None:
                    stack[-1] = 0
                pc += 1
            elif op == OP_RANGE_AGG:
                _, agg_kind, min_r, max_r, min_c, max_c, end_label = instr
                acc = stack[-1]
                if cursor is None:
                    r, c = min_r, min_c
                else:
                    r, c = cursor
                paused = False
                errored = False
                while r <= max_r:
                    base = r * 26
                    while c <= max_c:
                        idx = base + c
                        v = memo[idx]
                        if v is MISSING:
                            c += 1
                            continue
                        if v is UNVISITED:
                            stack[-1] = acc
                            frames.append((cell_idx, code, pc, stack, (r, c)))
                            memo[idx] = IN_PROGRESS
                            cell_idx = idx
                            code = compile_formula(raw_formulas[idx])
                            pc = 0
                            stack = []
                            cursor = None
                            paused = True
                            break
                        if v is IN_PROGRESS:
                            v = "#CYCLE!"
                        if type(v) is str:
                            stack[-1] = v
                            cursor = None
                            pc = end_label
                            errored = True
                            break
                        if agg_kind == AGG_SUM:
                            acc += v
                        elif agg_kind == AGG_MIN:
                            if acc is None or v < acc:
                                acc = v
                        else:
                            if acc is None or v > acc:
                                acc = v
                        c += 1
                    if paused or errored:
                        break
                    r += 1
                    c = min_c
                if not paused and not errored:
                    stack[-1] = acc
                    cursor = None
                    pc += 1

    return {name: memo[idx] for name, idx in cell_entries}
